def check_iso(I,O,val):
    h,w=len(I),len(I[0])
    bad=[]
    for i in range(h):
        for j in range(w):
            if I[i][j]==val:
                nb=[I[a][b] for a in range(max(0,i-1),min(h,i+2)) for b in range(max(0,j-1),min(w,j+2))]
                if nb.count(val)==1 and O[i][j]!=0: bad.append((i,j))
    return bad
